OUT=ROOT/'data/bidding-zone-network-2025/europe-linked-clearing-robust-v1'


def report():
    summary=json.loads((OUT/'annual-summary.json').read_text());audit=json.loads((OUT/'audit.json').read_text());inputs=json.loads((OUT/'inputs.json').read_text())
    assert audit['summary_sha256']==digest(OUT/'annual-summary.json') and audit['inputs_sha256']==digest(OUT/'inputs.json')
    assert audit['auditor_sha256']==digest(ROOT/'tools/audit_priced_europe_2025.py')
