        row=dict(day=r['day'],status=r['status'],day_pipeline_seconds=r['day_seconds'],order_and_compile_seconds=r['compile_seconds'],allocation_solver_seconds=allocation,fixed_integer_pricing_solver_seconds=fixed,other_pricing_setup_loop_seconds=max(0.,r['seconds']-allocation-fixed),verification_save_overhead_seconds=max(0.,r['day_seconds']-r['compile_seconds']-r['seconds']),rounds=len(h),orders=r['order_count'],binary_decisions=r['binary_count'],gas_package_mw=r['gas_package_mw'],eligible_gas_mw=r['eligible_gas_mw'],offer_cost_gap_eur=r.get('conservative_cost_gap_eur'),original_matrix_residual_mw=check[r['day']]['original_matrix_residual_mw'] if r['day'] in check else None,duality_gap_eur=check[r['day']]['duality_gap_eur'] if r['day'] in check else None,storage_terminal_error_mwh=check[r['day']]['storage_terminal_error_mwh'] if r['day'] in check else None)
