    process_seconds=sum(r['process_wall_seconds'] for r in invocations);prepare_seconds=sum(r['source_preparation_seconds'] for r in invocations)
    completed_rows=[r for r in rows if r['status']=='price_checked_incumbent'];phase_keys=['order_and_compile_seconds','allocation_solver_seconds','fixed_integer_pricing_solver_seconds','other_pricing_setup_loop_seconds','verification_save_overhead_seconds'];phase_values=[sum(r[k] for r in completed_rows) for k in phase_keys]
    fig,axes=plt.subplots(1,2,figsize=(13,5));ax=axes[0];dates=np.array([r['day'] for r in passed],dtype='datetime64[D]');ax.plot(dates,times,color='#286b9b',lw=.8);ax.axhline(quant[0],color='#4c9227',ls='--',label=f'Median {quant[0]:.2f}s');ax.set_ylabel('Daily pipeline seconds');ax.set_title(f'{days} checked daily European books');ax.legend();ax.grid(alpha=.2)
    ax=axes[1];labels=['Book / compile','MILP allocation','Fixed LP pricing','Other pricing / setup','Verify / save'];ax.barh(labels,phase_values,color=['#8da0cb','#66c2a5','#fc8d62','#e78ac3','#a6d854']);ax.set_xlabel('Measured seconds, completed days');ax.set_title('Where the runtime went');ax.grid(axis='x',alpha=.2)
